.cace-header { width: 100%; font-family: sans-serif; }
.cace-header-banner { background: linear-gradient(to right, #b91c1c, #ea580c); padding: 1.5rem; color: #ffffff; position: relative; overflow: hidden; }
.cace-header-content { position: relative; z-index: 10; display: flex; justify-content: space-between; align-items: flex-start; }
.cace-header-title { font-size: 3rem; font-family: serif; letter-spacing: 0.05em; margin: 0; }
.cace-header-subtitle { margin-top: 0.5rem; font-size: 0.875rem; font-weight: 300; letter-spacing: 0.025em; border-top: 1px solid rgba(255,255,255,0.3); padding-top: 0.25rem; display: inline-block; }
.cace-header-info { text-align: right; font-size: 0.75rem; font-weight: 300; opacity: 0.9; line-height: 1.25; }
.cace-header-info p { margin: 0; }
.cace-header-socials { display: flex; justify-content: flex-end; gap: 0.75rem; margin-top: 0.25rem; padding-top: 0.25rem; border-top: 1px solid rgba(255,255,255,0.2); }
.cace-header-accent-circle { position: absolute; top: 0; right: 0; margin-top: -2.5rem; margin-right: -2.5rem; width: 10rem; height: 10rem; background: #ffffff; opacity: 0.05; border-radius: 9999px; filter: blur(40px); }
.cace-header-footer { display: flex; justify-content: space-between; align-items: center; padding: 0.5rem 1.5rem; border-bottom: 2px solid #b91c1c; background-color: #ffffff; }
.cace-header-footer-label { font-weight: 700; font-size: 0.875rem; color: #1f2937; text-transform: uppercase; }
.cace-header-footer-date { font-size: 0.75rem; color: #6b7280; }

.cace-patient-data { border: 2px solid #1f2937; padding: 0.75rem; background-color: #ffffff; }
.cace-patient-grid { display: grid; grid-template-columns: repeat(12, 1fr); gap: 0.5rem 0; font-size: 0.875rem; }
.cace-patient-label { font-weight: 700; color: #111827; }
.cace-patient-value { font-weight: 500; color: #1f2937; }
.span-2 { grid-column: span 2; }
.span-4 { grid-column: span 4; }
.span-10 { grid-column: span 10; }
.uppercase { text-transform: uppercase; }
.text-right { text-align: right; }
.padding-r { padding-right: 0.5rem; }

.cace-results-container { width: 100%; }
.cace-results-header { background-color: #f9fafb; border-top: 1px solid #e5e7eb; border-bottom: 1px solid #e5e7eb; padding: 0.25rem 0.5rem; font-weight: 700; font-size: 0.75rem; text-transform: uppercase; color: #374151; margin-bottom: 0.5rem; }
.cace-results-table { width: 100%; border-collapse: collapse; font-size: 0.75rem; border: 1px solid #000000; }
.cace-results-thead tr { text-align: left; font-weight: 700; color: #111827; text-transform: uppercase; letter-spacing: -0.025em; }
.cace-results-th { padding-bottom: 0.5rem; }
.cace-results-th.center { text-align: center; }
.cace-results-th.right { text-align: right; }
.cace-results-tbody { border-top: 1px solid #f3f4f6; }
.cace-results-td { padding: 0.5rem 0; }
.cace-results-td.highlighted { font-weight: 500; color: #1f2937; }
.cace-results-td.center { text-align: center; }
.cace-results-td.right { text-align: right; }
.cace-results-td.bold { font-weight: 700; }
.cace-results-td.muted { color: #6b7280; }
.cace-results-td.medium { color: #4b5563; }
