.cace-footer { display: grid; grid-template-columns: 1fr 1fr; align-items: flex-end; border-top: 2px solid #f3f4f6; padding-top: 1rem; }
.cace-footer-qr { width: 4rem; height: 4rem; background-color: #111827; display: flex; align-items: center; justify-content: center; color: #ffffff; font-size: 9px; }
