.cace-footer-sign-info { font-size: 0.75rem; color: #6b7280; }
.cace-footer-sign-line { height: 2px; background-color: #000000; width: 100%; margin-top: 0.25rem; }

.diag-header { width: 100%; text-align: center; padding-bottom: 0.5rem; }
